import{_ as s,l,o as a,c as d,v as o,p as i,x as t,d as n,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"存储集预测","description":"","frontmatter":{"title":"存储集预测","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/store-set-predict.md","filePath":"cs/store-set-predict.md","lastUpdated":1789023840000}'),E={name:"cs/store-set-predict.md"};function S(C,e,h,A,P,_){const r=l("Mermaid");return a(),d("div",null,[e[1]||(e[1]=o('<h1 id="存储集预测" tabindex="-1">存储集预测 <a class="header-anchor" href="#存储集预测" aria-label="Permalink to &quot;存储集预测&quot;">​</a></h1><div class="epigraph"><p>多数 load 从不撞前面未完成的 store；少数 PC 对反复冲突。给会冲突的 load/store 打上同一集合号，让 load 等到该集合的 store 地址齐。 </p><footer>—— 据 Chrysos and Emer, Memory Dependence Prediction Using Store Sets, ISCA 1998 整理</footer></div><p><a href="/cs/lsq-disambiguation">上一课</a>在地址未知时只能全局地等或盲目推测。等则 ILP 掉；盲目则少量真冲突造成 replay 风暴。本课不重画 SQ CAM。缺口是<strong>用历史预测「这个 load 会依赖哪个 store」</strong>，而不是对所有年长 store 保守等待。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>循环里 <code>*p = …; … = *q</code> 若 <code>p</code> 与 <code>q</code> 几乎总不同，让 load 等 store 的 AGU 是冤枉的。若几乎总相同，放行则每次 replay。冲突关系更随 <strong>PC 对</strong> 而不是绝对地址稳定：同一 load PC 总是撞同一 store PC。缺口不是更大的 SQ，而是<strong>一张预测表：load PC 映射到它应当等待的 store 集合</strong>。</p><p><span class="marginnote">Chrysos–Emer 的 store set：冲突过的 load 与 store 被分进同一 SSID；load 发射受该 SSID 的「最后一个未完成 store」约束。不冲突的 PC 不进任何集合，可以自由提前。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>两张表：load PC → SSID；store PC → SSID。发现 replay（load 读到了不该看的 cache 值，年长 store 后来显示重叠）则把这对 PC 并入同一集合。预测：load 在 IQ 里除了寄存器就绪，还要「该 SSID 的 store 地址已决或已提交」。无 SSID 的 load 按无依赖发出。</p>',8)),(a(),i(c,null,{default:t(()=>[p(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20LDPC%5B%22load%20PC%22%5D%20--%3E%20SS%5B%22SSID%20%E8%A1%A8%22%5D%0A%20%20STPC%5B%22store%20PC%22%5D%20--%3E%20SS%0A%20%20SS%20--%3E%20WAIT%5B%22%E5%90%8C%E9%9B%86%E5%90%88%E5%88%99%E7%AD%89%E8%AF%A5%20store%20%E5%9C%B0%E5%9D%80%22%5D%0A%20%20SS%20--%3E%20FREE%5B%22%E6%97%A0%E9%9B%86%E5%90%88%E5%88%99%E6%8F%90%E5%89%8D%E5%8F%91%22%5D%0A%20%20CAM%5B%22%E7%9C%9F%E5%AE%9E%E5%9C%B0%E5%9D%80%20CAM%22%5D%20--%3E%7C%22%E6%84%8F%E5%A4%96%E5%86%B2%E7%AA%81%22%7C%20TRAIN%5B%22%E8%AE%AD%E7%BB%83%EF%BC%9A%E5%B9%B6%E5%85%A5%E5%90%8C%E4%B8%80%20SSID%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<p>真实 CAM 仍在：预测只减少等待，不取消消歧。漏报（该等没等）仍 replay 并训练；误报（不该等却等）只损失 ILP。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>与<a href="/cs/gshare-predictor">分支预测</a> 对照：分支猜方向，存储集猜依赖边。两者都是微结构表，以提交/核对更新，误路径要避免污染。SSID 有限，不同 PC 对会别名，表现为多余等待，通常比漏报便宜。</p><p>这为「值预测」让路：若连数据都可以猜，依赖边可能被绕过；但内存依赖仍必须在架构上正确，预测只能加速，不能代替 CAM。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 load 的返回值拿去预测——那是下一课值预测。也不保证多核上的依赖：他核 store 不在本核 store set 里，靠一致性与内存模型。SQ 满、SSID 饱和时退回保守。</p><p>后课默认：大多数 load 被预测为无内存依赖；冲突 PC 对被集中管理。寄存器与内存之外，运算结果本身能否猜，是下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>store set 按 PC 对学习内存依赖，减少盲目等待与盲目 replay。</li><li>真实地址 CAM 仍是正确性来源。</li><li>预测运算结果（而不只是依赖边）是下一课值预测。</li><li>出处：Chrysos and Emer, <em>ISCA</em>, 1998。</li></ul>',9))])}const u=s(E,[["render",S]]);export{D as __pageData,u as default};
